"""Write static/simulators/outages.json: outage cases for the design simulator.

Each case is a system shown breaking, then fixed. Real cases follow a published postmortem
(linked in `sources`); what-if cases take a company's write-up about an upgrade and run the
design they replaced at the load they describe; composite cases are a common pattern, not one
company's outage. Lessons open with one (an ```outage block naming the case); cases with no
lesson are the incident archive in Ripple Ops. `happened` is the record and stays factual;
the simulated day only replays the mechanism, so its hours and numbers are illustrative.

Run it after editing, then `node --test tests/test_outages.cjs`, which checks every case breaks
from its starting design and passes with its fix.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, '..', 'static', 'simulators', 'outages.json')


def g(nodes, edges, settings=None):
    """nodes: [(defId, col, row, cfg, label)], edges: [(i, j)] by 1-based index."""
    out = {'nodes': [], 'edges': [], 'labels': {}}
    for i, n in enumerate(nodes, 1):
        node = {'id': f'n{i}', 'defId': n[0], 'x': 40 + n[1] * 190, 'y': 40 + n[2] * 96}
        if len(n) > 3 and n[3]:
            node['cfg'] = n[3]
        if len(n) > 4 and n[4]:
            out['labels'][node['id']] = n[4]
        out['nodes'].append(node)
    out['edges'] = [{'id': f'e{k}', 'from': f'n{a}', 'to': f'n{b}'} for k, (a, b) in enumerate(edges, 1)]
    if settings:
        out['settings'] = settings
    return out


