def build():
    cases = []
    for c in CASES:
        c = {**c, 'section': c.get('section') or ('ai' if c['scenario'].get('ai') else 'system-design')}
        c['scenario'] = {'id': 'outage-' + c['id'], 'title': c['title'], **c['scenario']}
        cases.append(c)
    return {'version': 1, 'cases': cases}


def main():
    out = build()
    with open(OUT, 'w', encoding='utf-8') as fh:
        json.dump(out, fh, ensure_ascii=False, indent=1)
        fh.write('\n')
    print(f'wrote {len(out["cases"])} cases to {os.path.relpath(OUT)}')


if __name__ == '__main__':
    main()
